/* MY MONEY — no third-party scripts, no build step. */
'use strict';
const LOCAL_KEY='mymoney_local_v1', CLOUD_KEY='mymoney_cloud_config_v1', SESSION_KEY='mymoney_session_v1';
const $=s=>document.querySelector(s);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc;
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',transactions:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',analytics:'<path d="M4 20V10m5 10V4m5 16v-7m5 7V8"/>',goals:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',settings:'<path d="M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M18.4 5.6 17 7M7 17l-1.4 1.4"/><circle cx="12" cy="12" r="5"/>',wallet:'<rect x="2" y="6" width="20" height="15" rx="3"/><path d="M5 6V4a2 2 0 0 1 2-2h12v4M16 13h6"/><circle cx="16" cy="13" r=".7" fill="currentColor"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="m15 18-6-6 6-6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/>',hide:'<path d="m3 3 18 18M10 5c.7-.2 1.3-.3 2-.3 6 0 10 7.3 10 7.3a17 17 0 0 1-3.2 3.7M6 6C3.5 7.7 2 12 2 12s4 7 10 7c1.6 0 3.1-.5 4.4-1.2"/>',edit:'<path d="m14 4 6 6M4 20l4.5-1 11-11a2 2 0 0 0-3-3l-11 11z"/>',trash:'<path d="M4 7h16M9 7V4h6v3m3 0-1 14H7L6 7M10 11v7m4-7v7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',cloud:'<path d="M20 17.6a5 5 0 0 0-1-9.9 7 7 0 0 0-13 2.4A4 4 0 0 0 6 18h13"/>',shield:'<path d="m12 2 9 4v6c0 5-3.5 8.5-9 10-5.5-1.5-9-5-9-10V6z"/><path d="m8 12 3 3 5-6"/>',piggy:'<path d="M5 9c1-4 5-6 9-5l2 2h4l-1 4a7 7 0 0 1-3 9v2h-3v-2H8v2H5v-5C2 15 2 11 5 9zM3 12H1"/><circle cx="15" cy="10" r=".6" fill="currentColor"/>',chart:'<path d="M3 3v18h18M6 16l4-4 4 2 6-8"/>',credit:'<rect x="2" y="5" width="20" height="15" rx="2"/><path d="M2 10h20M6 16h4"/>',layers:'<rect x="3" y="4" width="18" height="6" rx="2"/><rect x="3" y="14" width="18" height="6" rx="2"/>',repeat:'<path d="m17 2 4 4-4 4M3 11V8a2 2 0 0 1 2-2h16M7 22l-4-4 4-4m14-1v3a2 2 0 0 1-2 2H3"/>',logout:'<path d="M9 4H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h4M14 7l5 5-5 5m5-5H8"/>',check:'<path d="m4 12 5 5L20 6"/>',chevron:'<path d="m9 18 6-6-6-6"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10v1"/>',refresh:'<path d="M20 6V2l-4 4 4 4M4 18v4l4-4-4-4"/><path d="M20 11a8 8 0 0 0-14-5M4 13a8 8 0 0 0 14 5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
function ico(name,size=19){return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true">${icons[name]||icons.wallet}</svg>`}
const fmt=n=>'₩'+Math.round(Number(n)||0).toLocaleString('ko-KR');
const fmtNum=n=>Math.round(Number(n)||0).toLocaleString('ko-KR');
const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dayOffset=n=>{let d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const monthKey=(d=today())=>d.slice(0,7);
const startMonth=()=>monthKey(today());
const monthLabel=k=>{const [y,m]=k.split('-');return `${y}년 ${Number(m)}월`};
const uuid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const cats={expense:[{name:'식비',emoji:'🍜',color:'#4ca477'},{name:'쇼핑',emoji:'🛍️',color:'#eaa65a'},{name:'교통',emoji:'🚆',color:'#5383c3'},{name:'구독',emoji:'🎵',color:'#a082bd'},{name:'주거',emoji:'🏠',color:'#ca8275'},{name:'건강',emoji:'💊',color:'#d77da0'},{name:'생활',emoji:'🧺',color:'#7ba59e'},{name:'기타',emoji:'📦',color:'#8c9c92'}],income:[{name:'급여',emoji:'💼'},{name:'외주',emoji:'🎨'},{name:'사업',emoji:'🛒'},{name:'기타 수입',emoji:'💰'}]};
function blankData(){return {version:1,isSample:false,accounts:[{id:uuid(),name:'현금',balance:0,emoji:'💵'}],transactions:[],budgets:[{id:uuid(),category:'식비',limit:150000},{id:uuid(),category:'쇼핑',limit:70000},{id:uuid(),category:'교통',limit:50000}],goals:[],recurring:[],categories:structuredClone(cats),preferences:{hideMoney:false}}}
function sampleData(){let d=blankData();d.isSample=true;const a=uuid(),b=uuid(),c=uuid();d.accounts=[{id:a,name:'국민은행',balance:800000,emoji:'🏦'},{id:b,name:'토스뱅크',balance:300000,emoji:'💳'},{id:c,name:'현금',balance:150000,emoji:'💵'}];d.transactions=[{id:uuid(),type:'expense',name:'카페',amount:4500,category:'식비',date:today(),accountId:a,memo:''},{id:uuid(),type:'income',name:'디자인 외주',amount:300000,category:'외주',date:dayOffset(-1),accountId:b,memo:''},{id:uuid(),type:'expense',name:'식료품',amount:32000,category:'식비',date:dayOffset(-2),accountId:a,memo:''},{id:uuid(),type:'expense',name:'Spotify',amount:10900,category:'구독',date:dayOffset(-3),accountId:a,memo:''},{id:uuid(),type:'expense',name:'지하철',amount:1550,category:'교통',date:dayOffset(-4),accountId:c,memo:''},{id:uuid(),type:'expense',name:'온라인 쇼핑',amount:28000,category:'쇼핑',date:dayOffset(-5),accountId:b,memo:''},{id:uuid(),type:'expense',name:'생활용품',amount:19000,category:'생활',date:dayOffset(-6),accountId:a,memo:''}];d.budgets=[{id:uuid(),category:'식비',limit:150000},{id:uuid(),category:'쇼핑',limit:100000},{id:uuid(),category:'교통',limit:50000},{id:uuid(),category:'구독',limit:40000},{id:uuid(),category:'생활',limit:70000}];d.goals=[{id:uuid(),name:'독립 자금',target:10000000,saved:2500000,emoji:'🏡'},{id:uuid(),name:'비상금',target:1000000,saved:600000,emoji:'🛟'}];d.recurring=[{id:uuid(),name:'Spotify',amount:10900,category:'구독',day:15,active:true},{id:uuid(),name:'iCloud',amount:1100,category:'구독',day:18,active:true},{id:uuid(),name:'YouTube Premium',amount:14900,category:'구독',day:20,active:false}];return d}
function readJson(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
let data=readJson(LOCAL_KEY,null);if(!data||!data.accounts||!Array.isArray(data.transactions)){data=sampleData();try{localStorage.setItem(LOCAL_KEY,JSON.stringify(data))}catch{}}
let config=readJson(CLOUD_KEY,{url:'',key:''}),session=readJson(SESSION_KEY,null);
let ui={view:'home',modal:null,month:startMonth(),type:'expense',filter:'all',search:'',editingId:null,selectedAccount:null,authMode:'login',authBusy:false,visibleStats:'expense',toastTimer:null,sync:'local',syncTimer:null,cloudBusy:false};
function byId(arr,id){return arr.find(x=>x.id===id)}
function txsForMonth(k=ui.month){return data.transactions.filter(t=>monthKey(t.date)===k)}
function totals(k=ui.month){const rows=txsForMonth(k);return {income:rows.filter(t=>t.type==='income').reduce((s,t)=>s+t.amount,0),expense:rows.filter(t=>t.type==='expense').reduce((s,t)=>s+t.amount,0)}}
function balance(){return data.accounts.reduce((s,a)=>s+a.balance,0)}
function spent(category,k=ui.month){return txsForMonth(k).filter(t=>t.type==='expense'&&t.category===category).reduce((s,t)=>s+t.amount,0)}
function totalBudget(){return data.budgets.reduce((s,b)=>s+b.limit,0)}
function monthShift(k,step){let [y,m]=k.split('-').map(Number);let d=new Date(y,m-1+step,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function num(v,max=1_000_000_000_000){let n=Number(v);return Number.isSafeInteger(n)&&n>=0&&n<=max?n:null}
function reveal(n){return data.preferences?.hideMoney?'₩ •••••':fmt(n)}
function progress(used,goal){let pct=goal>0?Math.round(used/goal*100):0;return `<div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,pct)}"><div class="progress-fill ${pct>100?'over':''}" style="width:${Math.min(100,Math.max(0,pct))}%"></div></div>`}
function catObj(name,type='expense'){return (data.categories[type]||[]).find(c=>c.name===name)||{name,emoji:'📦',color:'#88a08f'}}
function toast(message){const el=$('#toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(ui.toastTimer);ui.toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
function saveData(message){if(session){localStorage.setItem('mymoney_cloud_cache_'+session.user.id,JSON.stringify(data));ui.sync='pending';clearTimeout(ui.syncTimer);ui.syncTimer=setTimeout(syncCloud,650)}else{try{localStorage.setItem(LOCAL_KEY,JSON.stringify(data));ui.sync='local'}catch{toast('기기 저장 공간이 부족합니다. 백업 파일을 내보내세요.')}}if(message)toast(message);render()}
function setView(view){ui.view=view;ui.modal=null;ui.search='';render();window.scrollTo({top:0,behavior:'instant'})}
function showModal(type,id=null){ui.modal=type;ui.editingId=id;ui.type=(type==='tx'&&id)?byId(data.transactions,id)?.type||'expense':'expense';render();requestAnimationFrame(()=>{const el=$('.modal input:not([type=hidden]),.modal select');el?.focus({preventScroll:true})})}
function closeModal(){ui.modal=null;ui.editingId=null;render()}
const nav=[['home','홈','home'],['transactions','거래','transactions'],['analytics','분석','analytics'],['goals','목표','goals'],['settings','설정','settings']];
const more=[['budgets','예산 관리','chart'],['accounts','자산 관리','wallet'],['recurring','정기 결제','repeat'],['backup','백업 및 복원','cloud'],['categories','카테고리','layers']];
function monthSelector(){return `<div class="btn-row" style="align-items:center"><button class="icon-btn" aria-label="이전 달" data-action="month" data-step="-1">${ico('back',17)}</button><b style="min-width:88px;text-align:center;font-size:12px">${monthLabel(ui.month)}</b><button class="icon-btn" aria-label="다음 달" data-action="month" data-step="1">${ico('chevron',17)}</button></div>`}
function topbar(){let titles={home:'안녕하세요!',transactions:'거래 기록',analytics:'재정 분석',goals:'저축 목표',settings:'설정',budgets:'예산 관리',accounts:'자산 관리',recurring:'정기 결제',backup:'백업 및 복원',categories:'카테고리 관리',cloud:'클라우드 계정'};let subs={home:'오늘도 나의 재정을 차근차근',transactions:'수입과 지출을 한눈에',analytics:'나의 소비 패턴 살펴보기',goals:'조금씩 쌓아가는 나의 미래',settings:'개인정보와 앱 관리',budgets:'내 소비의 기준 만들기',accounts:'계좌와 현금을 직접 관리해요',recurring:'정기적으로 나가는 돈 정리',backup:'소중한 재정 기록 보호하기',categories:'내게 맞는 분류 정하기',cloud:'로그인 및 클라우드 동기화'};return `<header class="topbar"><div><p class="eyebrow">${esc(subs[ui.view]||'MY MONEY')}</p><h1 class="page-title">${esc(titles[ui.view]||'MY MONEY')}</h1></div><div class="top-actions"><span class="chip">${ico(session?'cloud':'lock',13)} ${session?'클라우드':'이 기기에 저장'}</span><button class="icon-btn" data-view="settings" title="설정" aria-label="설정">${ico('settings')}</button><button class="btn primary desktop-add" data-action="new-tx">${ico('plus',17)} 거래 추가</button></div></header>`}
function sidebar(){return `<aside class="sidebar"><div class="brand"><div class="brand-logo">${ico('wallet',26)}</div><div><strong>MY MONEY</strong><small>Your money. Your future.</small></div></div><div class="side-label">OVERVIEW</div>${nav.map(([id,label,icon])=>`<button class="side-item ${ui.view===id?'active':''}" data-view="${id}">${ico(icon)}${label}</button>`).join('')}<div class="side-label">MANAGE</div>${more.map(([id,label,icon])=>`<button class="side-item ${ui.view===id?'active':''}" data-view="${id}">${ico(icon)}${label}</button>`).join('')}<div class="side-footer"><b>${ico('shield',15)} 나만의 재정 공간</b>${session?'로그인 계정에 저장된 기록입니다.':'지금은 이 기기에 기록됩니다. 클라우드 로그인은 설정에서 연결하세요.'}</div></aside>`}
function mobileNav(){return `<nav class="mobile-nav" aria-label="메인 메뉴"><button aria-label="홈" class="${ui.view==='home'?'active':''}" data-view="home">${ico('home',22)}홈</button><button aria-label="거래" class="${ui.view==='transactions'?'active':''}" data-view="transactions">${ico('transactions',22)}거래</button><button aria-label="거래 추가" data-action="new-tx"><span class="add" style="display:grid;place-items:center">${ico('plus',23)}</span></button><button aria-label="분석" class="${ui.view==='analytics'?'active':''}" data-view="analytics">${ico('analytics',22)}분석</button><button aria-label="설정 및 기타" class="${['settings','budgets','accounts','recurring','backup','categories','cloud','goals'].includes(ui.view)?'active':''}" data-view="settings">${ico('settings',22)}설정</button></nav>`}
function section(title,view,label='전체 보기'){return `<div class="section-heading"><h2>${title}</h2>${view?`<button class="text-btn" data-view="${view}">${label} →</button>`:''}</div>`}
function demoRibbon(){return data.isSample?`<div class="demo-ribbon"><span>✦ 지금 보이는 금액은 <b>체험용 샘플 데이터</b>야.</span><button data-action="blank">내 기록 시작</button></div>`:''}
function txRow(t,showEdit=false){let cat=t.type==='transfer'?{emoji:'↔️'}:catObj(t.category,t.type);let col=t.type==='expense'?'negative':t.type==='income'?'positive':'';let sign=t.type==='expense'?'- ':t.type==='income'?'+ ':'';let from=byId(data.accounts,t.accountId),to=byId(data.accounts,t.toAccountId);return `<div class="tx-row"><div class="tx-icon ${t.type==='income'?'blue':t.type==='transfer'?'pink':t.category==='쇼핑'?'orange':''}">${esc(cat.emoji||'💳')}</div><div class="tx-meta"><span class="tx-name">${esc(t.name)}</span><div class="tx-detail">${esc(t.date)} · ${esc(t.type==='transfer'?`${from?.name||'삭제된 계좌'} → ${to?.name||'삭제된 계좌'}`:t.category)}</div></div><div class="tx-amount ${col}">${data.preferences.hideMoney?'••••':sign+fmt(t.amount)}</div>${showEdit?`<button class="tx-action" title="수정" aria-label="${esc(t.name)} 수정" data-action="edit-tx" data-id="${attr(t.id)}">${ico('edit',16)}</button>`:''}</div>`}
function home(){const t=totals(),budget=totalBudget(),rows=txsForMonth().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return `${demoRibbon()}<div class="hero"><div class="hero-bottom"><small>총 보유 자산 · 계좌 + 현금</small><button data-action="toggle-hidden" aria-label="금액 표시 전환">${ico(data.preferences.hideMoney?'hide':'eye',15)} ${data.preferences.hideMoney?'보기':'숨기기'}</button></div><div class="hero-value">${reveal(balance())}</div><div class="hero-bottom"><small>내가 직접 입력한 계좌 잔액 기준</small><button data-view="accounts">자산 보기 →</button></div></div><div class="summary-grid"><div class="card"><div class="kpi-icon">${ico('chart')}</div><div class="kpi-label">${monthLabel(ui.month)} 수입</div><div class="kpi-value positive">${reveal(t.income)}</div></div><div class="card"><div class="kpi-icon" style="background:#fff0ef;color:#ce6460">${ico('credit')}</div><div class="kpi-label">${monthLabel(ui.month)} 지출</div><div class="kpi-value negative">${reveal(t.expense)}</div></div><div class="card"><div class="kpi-icon">${ico('piggy')}</div><div class="kpi-label">이번 달 남은 예산</div><div class="kpi-value">${reveal(Math.max(0,budget-t.expense))}</div><div class="subtle">${budget?Math.round(t.expense/budget*100)+'% 사용':'예산 미설정'} ${t.expense>budget&&budget?' · 초과':''}</div>${progress(t.expense,budget)}</div></div><div class="two-col"><div>${section('저축 목표','goals')}<div class="card">${data.goals.length?data.goals.slice(0,3).map(g=>`<div class="goal-line"><div class="progress-head"><b><span class="goal-emoji">${esc(g.emoji)}</span>${esc(g.name)}</b><span>${g.target?Math.round(g.saved/g.target*100):0}%</span></div>${progress(g.saved,g.target)}<div class="subtle">${reveal(g.saved)} / ${reveal(g.target)}</div></div>`).join(''):`<div class="empty">${ico('goals',25)}<b>저축 목표가 없어</b>첫 번째 목표를 만들어보자.</div>`}<button class="btn outline full" style="margin-top:13px" data-action="new-goal">${ico('plus',15)} 목표 추가</button></div></div><div>${section('최근 거래','transactions')}<div class="card">${rows.length?rows.map(t=>txRow(t)).join(''):`<div class="empty"><div class="empty-icon">🧾</div><b>이번 달 거래가 없어</b>아래 버튼을 눌러 첫 거래를 기록해 봐.</div>`}<button class="btn secondary full" style="margin-top:14px" data-action="new-tx">${ico('plus',16)} 거래 기록하기</button></div></div></div><div class="section-heading"><h2>빠른 관리</h2></div><div class="btn-row"><button class="btn outline" data-view="budgets">${ico('chart')} 예산</button><button class="btn outline" data-view="recurring">${ico('repeat')} 정기 결제</button><button class="btn outline" data-view="backup">${ico('download')} 백업</button></div><div style="margin-top:15px">${monthSelector()}</div>`}
function transactionsPage(){let rows=txsForMonth().filter(t=>ui.filter==='all'||t.type===ui.filter).filter(t=>!ui.search||`${t.name} ${t.category} ${t.memo}`.toLowerCase().includes(ui.search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));let t=totals();return `${demoRibbon()}<div class="card" style="margin-bottom:16px"><div class="progress-head"><div><div class="kpi-label">이번 달 총 지출</div><div class="pill-amount negative" style="margin:7px 0">${reveal(t.expense)}</div></div>${monthSelector()}</div><div class="rule"></div><div class="progress-head"><span>수입 <b class="positive">${reveal(t.income)}</b></span><span>차액 <b>${reveal(t.income-t.expense)}</b></span></div></div><div class="tabline">${[['all','전체'],['expense','지출'],['income','수입'],['transfer','이체']].map(([k,n])=>`<button data-action="tx-filter" data-value="${k}" class="${ui.filter===k?'selected':''}">${n}</button>`).join('')}</div><div class="filterbar"><input class="input" id="tx-search" placeholder="거래 검색 (입력 후 Enter)" aria-label="거래 검색" value="${attr(ui.search)}" style="max-width:280px"><button class="btn primary" data-action="new-tx">${ico('plus',15)} 추가</button></div><div class="card">${rows.length?rows.map(t=>txRow(t,true)).join(''):`<div class="empty"><div class="empty-icon">🧾</div><b>표시할 거래가 없어</b>다른 달 또는 필터를 선택해 보거나 거래를 추가해 줘.</div>`}</div><div class="notice">계좌 간 이체는 수입·지출 합계에 포함되지 않아. 입력한 거래는 선택한 계좌 잔액에도 반영돼.</div>`}
function budgetsPage(){let total=totalBudget(),used=totals().expense;return `${demoRibbon()}<div class="card" style="margin-bottom:16px"><div class="progress-head"><div><div class="kpi-label">${monthLabel(ui.month)} 전체 예산</div><div class="pill-amount" style="margin:8px 0">${reveal(total)}</div></div>${monthSelector()}</div>${progress(used,total)}<div class="progress-head"><span>${reveal(used)} 사용</span><span>${total?Math.round(used/total*100):0}%</span></div></div>${section('카테고리별 예산')}<div class="section-list">${data.budgets.map(b=>{let u=spent(b.category),pct=b.limit?Math.round(u/b.limit*100):0;return `<div class="card budget-card"><div class="progress-head"><b>${esc(catObj(b.category).emoji)} ${esc(b.category)}</b><span>${pct>100?'<span class="tag red">초과</span>':`${pct}%`}</span></div>${progress(u,b.limit)}<div class="progress-head"><span>${reveal(u)} 사용</span><span>${reveal(b.limit)} 한도</span></div><div class="btn-row"><button class="btn secondary small" data-action="edit-budget" data-id="${attr(b.id)}">예산 수정</button><button class="btn outline small" data-action="delete-budget" data-id="${attr(b.id)}">삭제</button></div></div>`}).join('')||'<div class="empty">예산이 없어. 새 예산을 만들어 줘.</div>'}</div><button class="btn primary full" style="margin-top:17px" data-action="new-budget">${ico('plus')} 예산 만들기</button><div class="notice">예산은 매달 반복되는 한도야. 지난달 거래나 다른 카테고리의 지출은 여기 계산되지 않아.</div>`}
function goalsPage(){let saved=data.goals.reduce((s,g)=>s+g.saved,0),target=data.goals.reduce((s,g)=>s+g.target,0);return `${demoRibbon()}<div class="card" style="margin-bottom:17px"><div class="kpi-label">저축 목표 달성률</div><div class="pill-amount" style="margin:8px 0">${target?Math.round(saved/target*100):0}%</div>${progress(saved,target)}<div class="subtle">${reveal(saved)} / ${reveal(target)} · ${data.goals.length}개 목표</div></div><div class="section-list">${data.goals.map(g=>`<div class="card"><div class="progress-head"><div><div style="font-size:25px;margin-bottom:7px">${esc(g.emoji)}</div><b style="font-size:16px">${esc(g.name)}</b></div><span class="tag">${g.target?Math.round(g.saved/g.target*100):0}%</span></div><div style="font-size:20px;font-weight:800;margin-top:17px">${reveal(g.saved)} <span class="subtle" style="font-weight:400;font-size:12px">/ ${reveal(g.target)}</span></div>${progress(g.saved,g.target)}<div class="btn-row" style="margin-top:14px"><button class="btn primary small" data-action="contribute" data-id="${attr(g.id)}">${ico('plus',15)} 저축 기록</button><button class="btn outline small" data-action="edit-goal" data-id="${attr(g.id)}">수정</button><button class="btn outline small" data-action="delete-goal" data-id="${attr(g.id)}">삭제</button></div></div>`).join('')||'<div class="empty"><div class="empty-icon">🎯</div><b>아직 목표가 없어</b>이사 자금이나 비상금 목표를 설정해 봐.</div>'}</div><button class="btn primary full" style="margin-top:16px" data-action="new-goal">${ico('plus')} 새로운 목표 만들기</button><div class="notice">저축 목표의 금액은 진행 상황을 추적하는 기록이야. 실제 계좌에서 돈을 차감하거나 추가하지 않아. 계좌 간 자금 이동은 거래의 ‘이체’를 이용해 줘.</div>`}
function accountsPage(){return `${demoRibbon()}<div class="hero" style="min-height:150px;margin-bottom:19px"><small>총 보유 자산</small><div class="hero-value">${reveal(balance())}</div><small>수동 관리하는 계좌 및 현금 합계</small></div><div class="card">${data.accounts.map(a=>`<div class="account-row"><div class="account-left"><div class="account-symbol">${esc(a.emoji||'🏦')}</div><div><div class="account-name">${esc(a.name)}</div><div class="account-note">수동 관리 계좌</div></div></div><div style="text-align:right"><div class="account-amount">${reveal(a.balance)}</div><button class="text-btn" data-action="edit-account" data-id="${attr(a.id)}">수정</button></div></div>`).join('')||'<div class="empty">계좌가 없어.</div>'}</div><button class="btn primary full" style="margin-top:15px" data-action="new-account">${ico('plus')} 계좌 추가</button><div class="notice">자동 은행 연동은 없어. 계좌 잔액은 직접 입력하거나 거래를 기록하면서 변경돼. 현재 금액은 은행의 실제 잔액과 다를 수 있어.</div>`}
function recurringPage(){const monthly=data.recurring.filter(s=>s.active).reduce((s,x)=>s+x.amount,0);return `${demoRibbon()}<div class="card" style="margin-bottom:15px"><div class="kpi-label">활성 정기 결제 · 월 예상 합계</div><div class="pill-amount" style="margin-top:9px">${reveal(monthly)}</div></div><div class="card">${data.recurring.map(r=>`<div class="tx-row"><div class="tx-icon">${esc(catObj(r.category).emoji)}</div><div class="tx-meta"><span class="tx-name">${esc(r.name)}</span><div class="tx-detail">매월 ${r.day}일 · ${esc(r.category)}</div></div><div style="text-align:right"><b class="tx-amount">${reveal(r.amount)}</b><div style="display:flex;gap:5px;justify-content:flex-end;align-items:center;margin-top:5px"><input type="checkbox" data-recurring="${attr(r.id)}" aria-label="${attr(r.name)} 활성화" ${r.active?'checked':''}><button class="text-btn" data-action="edit-recurring" data-id="${attr(r.id)}">수정</button></div></div></div>`).join('')||'<div class="empty">정기 결제 항목이 없어.</div>'}</div><button class="btn primary full" style="margin-top:15px" data-action="new-recurring">${ico('plus')} 정기 결제 추가</button><div class="notice">예정된 비용을 기록하는 목록이야. <b>자동으로 거래를 추가하거나 실제 구독을 해지하지 않아.</b> 결제 후에는 거래 기록도 직접 추가해 줘.</div>`}
function analyticsPage(){let period=totals(),filtered=txsForMonth().filter(t=>t.type===ui.visibleStats),sum=filtered.reduce((s,t)=>s+t.amount,0),groups={};for(const t of filtered)groups[t.category]=(groups[t.category]||0)+t.amount;let palette=['#4cb586','#f3a957','#558ed1','#9876bd','#d87983','#78a4a0','#b39c60','#9daaa1'];let items=Object.entries(groups).sort((a,b)=>b[1]-a[1]);let offset=0;let segments=items.map(([k,v],i)=>{let start=offset;offset+=v;return `${palette[i%palette.length]} ${start/sum*100}% ${offset/sum*100}%`});let keys=Array.from({length:6},(_,i)=>monthShift(ui.month,i-5));let vals=keys.map(k=>totals(k).expense);let max=Math.max(...vals,1);return `${demoRibbon()}<div class="summary-grid" style="grid-template-columns:repeat(2,1fr)"><div class="card"><div class="kpi-label">${monthLabel(ui.month)} 수입</div><div class="kpi-value positive">${reveal(period.income)}</div></div><div class="card"><div class="kpi-label">${monthLabel(ui.month)} 지출</div><div class="kpi-value negative">${reveal(period.expense)}</div></div></div><div class="two-col"> <div class="card"><div class="progress-head"><b>카테고리 분석</b>${monthSelector()}</div><div class="tabline">${[['expense','지출'],['income','수입']].map(([id,n])=>`<button class="${ui.visibleStats===id?'selected':''}" data-action="stats-type" data-value="${id}">${n}</button>`).join('')}</div>${sum?`<div class="donut" style="background:conic-gradient(${segments.join(',')})"><div class="donut-core"><small class="subtle">${ui.visibleStats==='expense'?'총 지출':'총 수입'}</small><b>${reveal(sum)}</b></div></div>${items.map(([k,v],i)=>`<div class="legend-line"><span><i class="legend-dot" style="background:${palette[i%palette.length]}"></i>${esc(k)}</span><span>${Math.round(v/sum*100)}% · ${reveal(v)}</span></div>`).join('')}`:'<div class="empty">이번 달 분석할 거래가 없어.</div>'}</div><div class="card"><b>최근 6개월 지출 추이</b><div class="mini-bar-chart">${keys.map((k,i)=>`<div class="mini-bar-item"><span>${data.preferences.hideMoney?'••':Math.round(vals[i]/1000)+'k'}</span><div class="bar" style="height:${Math.max(3,vals[i]/max*132)}px"></div><span>${Number(k.slice(5))}월</span></div>`).join('')}</div><div class="rule"></div><div class="kpi-label">${monthLabel(ui.month)} 순현금흐름 (수입 − 지출)</div><div class="pill-amount ${period.income>=period.expense?'positive':'negative'}" style="margin-top:8px">${reveal(period.income-period.expense)}</div><div class="notice">월별 통계는 입력된 거래 내역 기준이야. 총 보유 자산과는 계산 기준이 달라.</div></div></div>`}
function settingsPage(){return `${demoRibbon()}<div class="card"><div class="account-row"><div class="account-left"><div class="account-symbol">${ico('shield',21)}</div><div><div class="account-name">${session?esc(session.user.email||'로그인된 계정'):'로컬 모드'}</div><div class="account-note">${session?'Supabase 클라우드 저장':'클라우드 로그인 미연결'}</div></div></div><span class="tag ${session?'':'yellow'}">${session?'로그인됨':'기기 저장'}</span></div></div>${section('나의 재정 관리')}<div class="card">${[['accounts','자산 관리','wallet'],['budgets','예산 관리','chart'],['recurring','정기 결제','repeat'],['categories','카테고리 관리','layers']].map(([v,n,i])=>`<button class="settings-link" data-view="${v}">${ico(i)}<span>${n}</span>${ico('chevron',15)}</button>`).join('')}</div>${section('데이터 및 보안')}<div class="card">${[['cloud','클라우드 로그인 및 동기화','cloud'],['backup','백업 및 복원','download']].map(([v,n,i])=>`<button class="settings-link" data-view="${v}">${ico(i)}<span>${n}</span>${ico('chevron',15)}</button>`).join('')}<button class="settings-link" data-action="toggle-hidden">${ico('eye')}<span>잔액 숨기기</span><span class="right">${data.preferences.hideMoney?'켜짐':'꺼짐'} ${ico('chevron',15)}</span></button></div>${section('앱 정보')}<div class="card"><div class="progress-head"><b>MY MONEY</b><span>Version 1.0</span></div><p class="fine-print">수동 입력 가계부 · 계좌 관리 · 예산 · 저축 · 분석 · 백업 · 선택적 Supabase 로그인과 클라우드 저장.</p><div class="status"><span class="status-dot ${session?(ui.sync==='synced'?'good':'wait'):'good'}"></span>${session?ui.sync==='synced'?'클라우드에 저장됨':ui.sync==='pending'?'클라우드 저장 대기':'클라우드 연결 확인 필요':'이 브라우저에 저장 중'}</div></div><div class="notice warn">공용 기기에서 사용하지 말고, 기기를 분실할 가능성에 대비해 정기적으로 백업해 줘. 클라우드 로그인이 완료되기 전에는 기기를 바꾸면 자동으로 기록이 이전되지 않아.</div>`}
function categoriesPage(){return `${demoRibbon()}${[['expense','지출'],['income','수입']].map(([type,label])=>` ${section(label+' 카테고리')}<div class="card">${(data.categories[type]||[]).map(c=>`<div class="account-row"><div class="account-left"><div class="account-symbol">${esc(c.emoji||'📦')}</div><b>${esc(c.name)}</b></div><button class="text-btn" data-action="delete-category" data-type="${type}" data-name="${attr(c.name)}">삭제</button></div>`).join('')||'<div class="empty">카테고리가 없어.</div>'}<button class="btn secondary full" style="margin-top:15px" data-action="new-category" data-type="${type}">${ico('plus')} ${label} 카테고리 추가</button></div>`).join('')}<div class="notice">이미 거래·예산·정기 결제에서 사용 중인 카테고리는 삭제할 수 없어.</div>`}
function backupPage(){return `${demoRibbon()}<div class="card" style="text-align:center;padding:30px 20px"><div style="display:grid;place-items:center;width:65px;height:65px;border-radius:21px;background:#e7f4e9;color:var(--forest);margin:auto">${ico('shield',32)}</div><h2 style="margin:17px 0 7px">재정 기록을 안전하게 보관해</h2><p class="subtle" style="line-height:1.6">JSON 파일은 모든 데이터를 백업·복원할 수 있고,<br>CSV 파일은 거래 기록을 표로 볼 때 좋아.</p></div><div class="section-heading"><h2>파일 백업</h2></div><div class="card"><b>전체 데이터 백업 (.json)</b><p class="fine-print">계좌, 거래, 예산, 저축 목표, 구독, 분류 전체를 저장해.</p><button class="btn primary full" data-action="export-json">${ico('download')} 전체 데이터 내보내기</button><div class="rule"></div><b>거래 내역 다운로드 (.csv)</b><p class="fine-print">Excel이나 스프레드시트에서 열어볼 수 있어. CSV는 전체 복원용 파일이 아니야.</p><button class="btn outline full" data-action="export-csv">${ico('download')} 거래 CSV 내보내기</button></div><div class="section-heading"><h2>백업 복원</h2></div><div class="card"><b>JSON 백업 파일 가져오기</b><p class="fine-print">복원하면 현재 화면의 모든 재정 기록을 새 파일의 기록으로 <b>교체</b>해. 기존 기록을 먼저 내보내 줘.</p><label class="btn outline full" style="cursor:pointer">${ico('upload')} JSON 파일 선택<input type="file" id="backup-file" accept=".json,application/json" style="display:none" /></label></div><div class="notice warn">백업 파일은 암호화되어 있지 않아. 아이폰 ‘파일’ 앱 또는 개인 보안 저장소에 안전하게 보관하고, 다른 사람에게 전달하지 마.</div>${session?'<div class="notice">로그인 중일 때 백업을 복원하면 연결된 클라우드 기록도 교체돼. 반드시 본인 계정인지 확인해.</div>':''}`}
function cloudPage(){const configured=!!(config.url&&config.key);return `${demoRibbon()}<div class="card" style="margin-bottom:15px"><div class="auth-hero"><div class="brand-logo">${ico('cloud',28)}</div><h2>MY MONEY Cloud</h2><p class="subtle">아이폰과 PC에서 같은 기록 사용하기</p></div>${session?`<div class="notice">${esc(session.user.email||'사용자')} 계정으로 로그인했어. ${ui.sync==='synced'?'최근 변경 사항이 클라우드에 저장됐어.':'동기화 상태를 확인해 줘.'}</div><div class="btn-row"><button class="btn primary" data-action="sync-now">${ico('refresh')} 지금 동기화</button><button class="btn outline" data-action="logout">${ico('logout')} 로그아웃</button></div>`:configured?`<div class="tabline"><button class="${ui.authMode==='login'?'selected':''}" data-action="auth-mode" data-value="login">로그인</button><button class="${ui.authMode==='signup'?'selected':''}" data-action="auth-mode" data-value="signup">회원가입</button><button class="${ui.authMode==='reset'?'selected':''}" data-action="auth-mode" data-value="reset">비밀번호 재설정</button></div><form data-form="auth"><label class="field">이메일<input class="input" required type="email" name="email" autocomplete="email" placeholder="you@example.com"></label>${ui.authMode!=='reset'?`<label class="field">비밀번호<input class="input" required minlength="6" type="password" name="password" autocomplete="${ui.authMode==='login'?'current-password':'new-password'}" placeholder="비밀번호 입력"></label>`:''}<button class="btn primary full" type="submit">${ui.authMode==='login'?'로그인':ui.authMode==='signup'?'회원가입':'재설정 이메일 보내기'}</button></form>`:`<div class="notice warn">클라우드 서비스를 아직 설정하지 않았어. 아래에 네 Supabase 프로젝트 정보(공개 URL·publishable/anon 키)를 연결해 줘.</div>`}</div><div class="card"><div class="progress-head"><b>Supabase 프로젝트 연결</b><span class="tag ${configured?'':'yellow'}">${configured?'설정됨':'미설정'}</span></div><p class="fine-print">Supabase에서 프로젝트를 만들고 제공된 SQL을 실행한 뒤 연결해 줘. service_role 또는 secret 키는 절대 입력하면 안 돼.</p><form data-form="cloud-config"><label class="field">프로젝트 URL<input class="input" name="url" type="url" placeholder="https://your-project.supabase.co" value="${attr(config.url||'')}" required></label><label class="field">Publishable 또는 anon 키<input class="input" name="key" type="text" placeholder="sb_publishable_... 또는 eyJ..." value="${attr(config.key||'')}" required></label><button class="btn outline full" type="submit">연결 정보 저장</button></form></div>${session?`<div class="card" style="margin-top:15px"><b>로컬 기록을 클라우드로 가져오기</b><p class="fine-print">현재 클라우드 기록을 로컬 기록으로 교체해. 두 기기에서 따로 기록을 쌓았다면 먼저 JSON 백업을 받아줘.</p><button class="btn outline full" data-action="upload-local">이 기기의 로컬 기록 업로드</button></div>`:''}<div class="notice">로그인과 클라우드 저장은 프로젝트 URL·키 및 서버의 RLS 보안 설정이 완료된 뒤 사용할 수 있어. 연결 전에도 로컬 모드의 모든 가계부 기능은 작동해. 동시 편집 시 마지막 저장이 우선될 수 있으므로 두 기기에서 동시에 수정하지 않는 것을 권장해.</div>`}
function page(){return ({home,transactions:transactionsPage,analytics:analyticsPage,goals:goalsPage,settings:settingsPage,budgets:budgetsPage,accounts:accountsPage,recurring:recurringPage,backup:backupPage,categories:categoriesPage,cloud:cloudPage}[ui.view]||home)()}
function render(){let el=$('#app');if(!el)return;el.innerHTML=`<div class="shell">${sidebar()}<main class="main"><div class="inner">${topbar()}${page()}</div></main>${mobileNav()}</div>${modalHtml()}`;document.body.style.overflow=ui.modal?'hidden':''}
function optionList(items,selected=''){return items.map(x=>`<option value="${attr(x.id??x.name)}" ${String(x.id??x.name)===String(selected)?'selected':''}>${esc(x.emoji?x.emoji+' ':'')}${esc(x.name)}</option>`).join('')}
function field(name,label,value='',type='text',extra=''){return `<label class="field">${label}<input class="input" name="${name}" type="${type}" value="${attr(value)}" ${extra}></label>`}
function modalHtml(){if(!ui.modal)return '';let id=ui.editingId,html='',heading='';if(ui.modal==='tx'){let t=byId(data.transactions,id)||null,k=ui.type;heading=t?'거래 수정':'새 거래 추가';let accounts=optionList(data.accounts,t?.accountId||data.accounts[0]?.id);html=`<div class="tabline">${[['expense','지출'],['income','수입'],['transfer','이체']].map(([x,n])=>`<button class="${k===x?'selected':''}" data-action="tx-type" data-value="${x}" ${t?'disabled title="수정 중에는 유형을 바꿀 수 없어"':''}>${n}</button>`).join('')}</div><form data-form="tx">${field('amount','금액 (원)',t?.amount||'','number','required min="1" step="1" max="1000000000000"')}${field('name','내용',t?.name||'','text','required maxlength="80" placeholder="예: 점심 식사"')}<div class="form-grid"><label class="field">${k==='transfer'?'보내는 계좌':'계좌'}<select class="select" name="accountId" required>${accounts}</select></label>${k==='transfer'?`<label class="field">받는 계좌<select class="select" name="toAccountId" required>${optionList(data.accounts,t?.toAccountId||data.accounts[1]?.id)}</select></label>`:`<label class="field">카테고리<select class="select" name="category" required>${optionList(data.categories[k]||[],t?.category)}</select></label>`}</div>${field('date','날짜',t?.date||today(),'date','required')}${field('memo','메모 (선택)',t?.memo||'','text','maxlength="200" placeholder="간단한 설명"')}<button class="btn primary full" type="submit">${t?'변경 사항 저장':'거래 저장'}</button>${t?`<button type="button" class="btn danger full" style="margin-top:9px" data-action="delete-tx" data-id="${attr(t.id)}">${ico('trash')} 거래 삭제</button>`:''}</form><div class="notice">계좌 잔액도 거래 종류에 맞춰 변경돼. 이체는 수입·지출에 포함되지 않아.</div>`}
if(ui.modal==='budget'){let b=byId(data.budgets,id);heading=b?'예산 수정':'새 예산';let used=data.budgets.map(x=>x.category);let available=data.categories.expense.filter(c=>b?.category===c.name||!used.includes(c.name));html=`<form data-form="budget"><label class="field">카테고리<select class="select" name="category" required>${optionList(available,b?.category)}</select></label>${field('limit','월간 예산 한도 (원)',b?.limit||'','number','required min="1" max="1000000000000"')}<button class="btn primary full">${b?'예산 수정':'예산 추가'}</button></form>`}
if(ui.modal==='goal'){let g=byId(data.goals,id);heading=g?'저축 목표 수정':'새 저축 목표';html=`<form data-form="goal">${field('name','목표 이름',g?.name||'','text','required maxlength="45" placeholder="예: 이사 자금"')}${field('emoji','아이콘',g?.emoji||'🎯','text','maxlength="6"')}${field('target','목표 금액 (원)',g?.target||'','number','required min="1" max="1000000000000"')}${g?field('saved','현재 달성액 (원)',g.saved,'number','required min="0" max="1000000000000"'):''}<button class="btn primary full">${g?'변경 사항 저장':'목표 만들기'}</button></form>`}
if(ui.modal==='contribute'){let g=byId(data.goals,id);heading=`${esc(g?.name||'목표')} 저축 기록`;html=`<form data-form="contribute"><label class="field">저축 또는 인출<select class="select" name="direction"><option value="add">저축액 추가</option><option value="subtract">저축액 차감</option></select></label>${field('amount','금액 (원)','','number','required min="1" max="1000000000000"')}<button class="btn primary full">기록 저장</button></form><div class="notice">목표 금액만 변경되며 실제 계좌 잔액이나 거래에 반영되지는 않아.</div>`}
if(ui.modal==='account'){let a=byId(data.accounts,id);heading=a?'계좌 수정':'새 계좌';html=`<form data-form="account">${field('name','계좌 이름',a?.name||'','text','required maxlength="45" placeholder="예: 국민은행"')}${field('emoji','아이콘',a?.emoji||'🏦','text','maxlength="6"')}${field('balance','현재 잔액 (원)',a?.balance??0,'number','required min="-1000000000000" max="1000000000000"')}<button class="btn primary full">${a?'수정 완료':'계좌 추가'}</button></form>${a?`<button class="btn danger full" style="margin-top:9px" data-action="delete-account" data-id="${attr(a.id)}">계좌 삭제</button>`:''}`}
if(ui.modal==='recurring'){let r=byId(data.recurring,id);heading=r?'정기 결제 수정':'정기 결제 추가';html=`<form data-form="recurring">${field('name','이름',r?.name||'','text','required maxlength="65" placeholder="예: Spotify"')}${field('amount','매월 결제 예정 금액',r?.amount||'','number','required min="1" max="1000000000000"')}<div class="form-grid"><label class="field">카테고리<select class="select" name="category">${optionList(data.categories.expense,r?.category||'구독')}</select></label>${field('day','매월 결제일',r?.day||15,'number','required min="1" max="31"')}</div><label class="checkbox"><input name="active" type="checkbox" ${r?.active!==false?'checked':''}>활성 정기 결제</label><button class="btn primary full">저장</button></form>${r?`<button class="btn danger full" style="margin-top:9px" data-action="delete-recurring" data-id="${attr(r.id)}">삭제</button>`:''}`}
if(ui.modal==='category'){heading='카테고리 추가';html=`<form data-form="category">${field('name','카테고리 이름','','text','required maxlength="30" placeholder="예: 반려견"')}${field('emoji','아이콘','🪴','text','maxlength="6"')}<input type="hidden" name="type" value="${attr(ui.type)}"><button class="btn primary full">추가하기</button></form>`}
return `<div class="modal-backdrop" data-action="backdrop" role="presentation"><div class="modal" role="dialog" aria-modal="true" aria-label="${attr(heading)}"><div class="modal-head"><h2>${heading}</h2><button class="close" data-action="close" aria-label="닫기">×</button></div>${html}</div></div>`}
function applyTx(t,direction=1){const from=byId(data.accounts,t.accountId),to=byId(data.accounts,t.toAccountId);if(!from)throw new Error('선택한 계좌가 존재하지 않아.');if(t.type==='expense')from.balance-=direction*t.amount;else if(t.type==='income')from.balance+=direction*t.amount;else if(t.type==='transfer'){if(!to||to.id===from.id)throw new Error('다른 두 계좌를 선택해 줘.');from.balance-=direction*t.amount;to.balance+=direction*t.amount} }
function submitForm(form){let fd=new FormData(form),name=form.dataset.form,id=ui.editingId;
 try{
 if(name==='tx'){let amount=num(fd.get('amount'));if(amount===null||amount<=0)throw Error('올바른 금액을 입력해 줘.');let n=String(fd.get('name')||'').trim();if(!n)throw Error('거래 내용을 입력해 줘.');let t={id:id||uuid(),type:ui.type,name:n.slice(0,80),amount,accountId:String(fd.get('accountId')||''),toAccountId:ui.type==='transfer'?String(fd.get('toAccountId')||''):null,category:ui.type==='transfer'?'이체':String(fd.get('category')||''),date:String(fd.get('date')||''),memo:String(fd.get('memo')||'').trim().slice(0,200)};if(!/^\d{4}-\d{2}-\d{2}$/.test(t.date)||Number.isNaN(Date.parse(t.date+'T12:00:00')))throw Error('올바른 날짜를 선택해 줘.');if(ui.type!=='transfer'&&!(data.categories[ui.type]||[]).some(c=>c.name===t.category))throw Error('유효한 카테고리를 선택해 줘.');let old=byId(data.transactions,id);if(old)applyTx(old,-1);try{applyTx(t,1)}catch(e){if(old)applyTx(old,1);throw e}if(old)Object.assign(old,t);else data.transactions.unshift(t);}
 else if(name==='budget'){let limit=num(fd.get('limit'));if(!limit)throw Error('예산을 올바르게 입력해 줘.');let category=String(fd.get('category')||'');if(!data.categories.expense.some(c=>c.name===category))throw Error('유효한 카테고리를 선택해 줘.');if(data.budgets.some(b=>b.id!==id&&b.category===category))throw Error('이미 해당 카테고리 예산이 있어.');let b=byId(data.budgets,id);if(b)Object.assign(b,{category,limit});else data.budgets.push({id:uuid(),category,limit});}
 else if(name==='goal'){let target=num(fd.get('target'));if(!target)throw Error('목표 금액을 입력해 줘.');let n=String(fd.get('name')||'').trim(),g=byId(data.goals,id);if(!n)throw Error('목표 이름을 입력해 줘.');let saved=g?num(fd.get('saved')):0;if(saved===null)throw Error('현재 저축액이 잘못됐어.');let entry={name:n.slice(0,45),target,saved,emoji:String(fd.get('emoji')||'🎯').slice(0,6)};if(g)Object.assign(g,entry);else data.goals.push({id:uuid(),...entry});}
 else if(name==='contribute'){let g=byId(data.goals,id),n=num(fd.get('amount'));if(!g||!n)throw Error('금액을 확인해 줘.');let saved=g.saved+(fd.get('direction')==='subtract'?-n:n);if(saved<0||!Number.isSafeInteger(saved)||saved>1e12)throw Error('저축액은 0원 이상이어야 해.');g.saved=saved;}
 else if(name==='account'){let b=Number(fd.get('balance'));if(!Number.isSafeInteger(b)||Math.abs(b)>1e12)throw Error('잔액을 올바르게 입력해 줘.');let n=String(fd.get('name')||'').trim();if(!n)throw Error('계좌 이름을 입력해 줘.');let entry={name:n.slice(0,45),balance:b,emoji:String(fd.get('emoji')||'🏦').slice(0,6)};let a=byId(data.accounts,id);if(a)Object.assign(a,entry);else data.accounts.push({id:uuid(),...entry});}
 else if(name==='recurring'){let amount=num(fd.get('amount')),day=num(fd.get('day'));if(!amount||!day||day>31)throw Error('금액과 결제일을 확인해 줘.');let n=String(fd.get('name')||'').trim();if(!n)throw Error('이름을 입력해 줘.');let entry={name:n.slice(0,65),amount,day,category:String(fd.get('category')||'기타'),active:fd.get('active')==='on'};let r=byId(data.recurring,id);if(r)Object.assign(r,entry);else data.recurring.push({id:uuid(),...entry});}
 else if(name==='category'){let n=String(fd.get('name')||'').trim(),type=String(fd.get('type'));if(!n||!['expense','income'].includes(type))throw Error('카테고리 이름을 확인해 줘.');if(data.categories[type].some(c=>c.name===n))throw Error('이미 같은 이름의 카테고리가 있어.');data.categories[type].push({name:n.slice(0,30),emoji:String(fd.get('emoji')||'📦').slice(0,6),color:'#8ba18e'});}
 else return;
 ui.modal=null;ui.editingId=null;saveData('저장했어.');
 }catch(error){toast(error.message||'저장할 수 없어.')}}
function validateData(d){if(!d||typeof d!=='object'||d.version!==1)throw Error('지원하지 않는 백업 형식이야.');for(const k of ['accounts','transactions','budgets','goals','recurring'])if(!Array.isArray(d[k])||d[k].length>30000)throw Error(`${k} 데이터가 올바르지 않아.`);if(!d.categories||!Array.isArray(d.categories.expense)||!Array.isArray(d.categories.income))throw Error('카테고리 데이터가 누락됐어.');let clean=JSON.parse(JSON.stringify(d));if(!clean.preferences||typeof clean.preferences!=='object')clean.preferences={hideMoney:false};clean.preferences.hideMoney=!!clean.preferences.hideMoney;for(const section of ['accounts','transactions','budgets','goals','recurring'])for(const row of clean[section]){if(!row||typeof row!=='object'||typeof row.id!=='string'||row.id.length>120)throw Error('항목 ID가 올바르지 않아.');if(row.name!==undefined&&(typeof row.name!=='string'||row.name.length>200))throw Error('이름 항목이 올바르지 않아.');for(const k of ['balance','amount','limit','target','saved','day'])if(row[k]!==undefined&&num(row[k])===null)throw Error('금액 데이터가 올바르지 않아.')}let accountIDs=new Set(clean.accounts.map(x=>x.id));if(accountIDs.size!==clean.accounts.length)throw Error('계좌 ID가 중복됐어.');for(const tx of clean.transactions){if(!['income','expense','transfer'].includes(tx.type)||!accountIDs.has(tx.accountId)||tx.amount<=0||typeof tx.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(tx.date))throw Error('거래 데이터가 올바르지 않아.');if(tx.type==='transfer'&&(!accountIDs.has(tx.toAccountId)||tx.accountId===tx.toAccountId))throw Error('이체 계좌 데이터가 올바르지 않아.');}for(const k of ['accounts','transactions','budgets','goals','recurring'])if(new Set(clean[k].map(x=>x.id)).size!==clean[k].length)throw Error('중복 항목 ID가 있어.');for(const k of ['expense','income']){if(clean.categories[k].length>200||clean.categories[k].some(x=>!x||typeof x.name!=='string'||x.name.length>50||typeof x.emoji!=='string'||x.emoji.length>32))throw Error('카테고리 데이터가 올바르지 않아.');}clean.isSample=!!clean.isSample;return clean}
function download(content,filename,mime){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type:mime}));a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function backupJSON(){download(JSON.stringify({app:'MY MONEY',version:1,exportedAt:new Date().toISOString(),data},null,2),'MY_MONEY_backup_'+today()+'.json','application/json;charset=utf-8');toast('전체 데이터 백업 파일을 만들었어.')}
function csvCell(x){let s=String(x??'');if(/^[\s]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function exportCSV(){let header=['날짜','구분','내용','카테고리','금액(KRW)','출금/입금 계좌','받는 계좌','메모'];let rows=data.transactions.map(t=>[t.date,t.type==='expense'?'지출':t.type==='income'?'수입':'이체',t.name,t.category,t.amount,byId(data.accounts,t.accountId)?.name||'',byId(data.accounts,t.toAccountId)?.name||'',t.memo||'']);download('\uFEFF'+[header,...rows].map(row=>row.map(csvCell).join(',')).join('\r\n'),'MY_MONEY_transactions_'+today()+'.csv','text/csv;charset=utf-8');toast('거래 CSV 파일을 만들었어.')}
async function restoreJSON(file){if(!file)return;if(file.size>10*1024*1024)return toast('백업 파일 크기는 10MB 이하여야 해.');try{let parsed=JSON.parse(await file.text());let value=validateData(parsed?.app==='MY MONEY'&&parsed?.data?parsed.data:parsed);if(!confirm(`백업의 거래 ${value.transactions.length}건으로 현재 기록을 전부 교체할까?\n\n기존 데이터를 되돌리려면 먼저 JSON 백업을 받아야 해.`))return;data=value;saveData('백업에서 복원했어.')}catch(err){toast('복원 실패: '+err.message)}}
async function authFetch(path,body,method='POST',token=null){if(!config.url||!config.key)throw Error('Supabase 프로젝트를 먼저 연결해 줘.');const r=await fetch(config.url+path,{method,headers:{'Content-Type':'application/json','apikey':config.key,...(token?{'Authorization':'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined});let v=await r.json().catch(()=>({}));if(!r.ok)throw Error(v.msg||v.message||v.error_description||v.error||`서버 오류 (${r.status})`);return v}
async function getToken(){if(!session)return null;if(Date.now()<(session.expiresAt||0)-90000)return session.access_token;try{let r=await authFetch('/auth/v1/token?grant_type=refresh_token',{refresh_token:session.refresh_token});session={access_token:r.access_token,refresh_token:r.refresh_token,expiresAt:Date.now()+r.expires_in*1000,user:r.user||session.user};localStorage.setItem(SESSION_KEY,JSON.stringify(session));return session.access_token}catch(e){ui.sync='error';toast('로그인 세션이 만료됐어. 다시 로그인해 줘.');return null}}
async function dataFetch(path,method='GET',payload=null){let token=await getToken();if(!token)throw Error('클라우드 로그인이 필요해.');let r=await fetch(config.url+'/rest/v1/'+path,{method,headers:{'apikey':config.key,'Authorization':'Bearer '+token,'Content-Type':'application/json','Prefer':'return=representation'},body:payload?JSON.stringify(payload):undefined});let value=await r.json().catch(()=>[]);if(!r.ok)throw Error(value.message||value.error||`클라우드 오류 (${r.status})`);return value}
async function loadCloud(){if(!session)return;ui.cloudBusy=true;try{const rows=await dataFetch('finance_data?select=payload,updated_at&user_id=eq.'+encodeURIComponent(session.user.id));if(rows.length&&rows[0].payload){data=validateData(rows[0].payload)}else{data=blankData();await dataFetch('finance_data','POST',{user_id:session.user.id,payload:data})}localStorage.setItem('mymoney_cloud_cache_'+session.user.id,JSON.stringify(data));ui.sync='synced';ui.view='home';toast('클라우드 기록을 불러왔어.')}catch(e){ui.sync='error';const cache=readJson('mymoney_cloud_cache_'+session.user.id,null);if(cache){try{data=validateData(cache);toast('오프라인 캐시를 불러왔어. 연결 상태를 확인해 줘.')}catch{toast(e.message)}}else{data=blankData();toast('클라우드 로딩 실패: '+e.message)}}finally{ui.cloudBusy=false;render()}}
async function syncCloud(){if(!session||ui.cloudBusy)return;ui.cloudBusy=true;const snapshot=JSON.stringify(data);try{await dataFetch('finance_data?user_id=eq.'+encodeURIComponent(session.user.id),'PATCH',{payload:JSON.parse(snapshot)});ui.sync=JSON.stringify(data)===snapshot?'synced':'pending';if(ui.sync==='pending')ui.syncTimer=setTimeout(syncCloud,600)}catch(e){ui.sync='error';toast('클라우드 저장 실패. 이 기기 캐시에 보관했어: '+e.message)}finally{ui.cloudBusy=false;render()}}
async function signInOrUp(form){let fd=new FormData(form),email=String(fd.get('email')||'').trim(),password=String(fd.get('password')||'');if(!email)return toast('이메일을 입력해 줘.');try{ui.authBusy=true;let r;if(ui.authMode==='reset'){await authFetch('/auth/v1/recover',{email});toast('재설정 이메일을 요청했어. 메일함을 확인해 줘.');return}if(password.length<6)throw Error('비밀번호는 6자 이상이어야 해.');if(ui.authMode==='signup'){r=await authFetch('/auth/v1/signup',{email,password});if(!r.access_token){toast('가입 요청을 보냈어. 이메일 인증 후 로그인해 줘.');ui.authMode='login';render();return}}else r=await authFetch('/auth/v1/token?grant_type=password',{email,password});if(!r.access_token||!r.user?.id)throw Error('로그인을 완료하지 못했어.');session={access_token:r.access_token,refresh_token:r.refresh_token,user:r.user,expiresAt:Date.now()+r.expires_in*1000};localStorage.setItem(SESSION_KEY,JSON.stringify(session));await loadCloud()}catch(e){toast('인증 실패: '+e.message)}finally{ui.authBusy=false}}
async function logout(){if(!session)return;clearTimeout(ui.syncTimer);if(ui.sync==='pending'&&!confirm('아직 클라우드 저장이 진행 중이야. 로그아웃할까?'))return;try{await authFetch('/auth/v1/logout',null,'POST',session.access_token)}catch{}session=null;localStorage.removeItem(SESSION_KEY);data=readJson(LOCAL_KEY,null)||sampleData();ui.sync='local';ui.view='home';render();toast('로그아웃했어. 로컬 기록으로 돌아왔어.')}
async function uploadLocal(){if(!session)return;const local=readJson(LOCAL_KEY,null);if(!local)return toast('업로드할 로컬 기록이 없어.');if(!confirm('이 기기의 로컬 데이터로 클라우드 기록을 전부 덮어쓸까?\n\n먼저 클라우드 기록을 JSON으로 백업하기를 권장해.'))return;try{data=validateData(local);await syncCloud();ui.view='home';render();toast('로컬 기록을 클라우드에 업로드했어.')}catch(e){toast('업로드 실패: '+e.message)}}
function deleteItem(type,id,extra){if(type==='tx'){let t=byId(data.transactions,id);if(!t||!confirm(`“${t.name}” 거래를 삭제할까? 계좌 잔액도 원래대로 돌아가.`))return;try{applyTx(t,-1);data.transactions=data.transactions.filter(x=>x.id!==id)}catch(e){return toast(e.message)}}
if(type==='budget'){let b=byId(data.budgets,id);if(!b||!confirm(`${b.category} 예산을 삭제할까?`))return;data.budgets=data.budgets.filter(x=>x.id!==id)}
if(type==='goal'){let g=byId(data.goals,id);if(!g||!confirm(`“${g.name}” 목표와 저축 기록을 삭제할까?`))return;data.goals=data.goals.filter(x=>x.id!==id)}
if(type==='account'){let a=byId(data.accounts,id);if(!a)return;if(data.transactions.some(t=>t.accountId===id||t.toAccountId===id))return toast('거래가 연결된 계좌는 삭제할 수 없어.');if(!confirm(`“${a.name}” 계좌를 삭제할까?`))return;data.accounts=data.accounts.filter(x=>x.id!==id)}
if(type==='recurring'){let r=byId(data.recurring,id);if(!r||!confirm(`“${r.name}” 정기 결제를 삭제할까?`))return;data.recurring=data.recurring.filter(x=>x.id!==id)}
if(type==='category'){let k=extra.kind,n=extra.name;if(data.transactions.some(t=>t.type===k&&t.category===n)||data.budgets.some(b=>b.category===n)||data.recurring.some(r=>r.category===n))return toast('현재 사용 중인 카테고리는 삭제할 수 없어.');if(!confirm(`“${n}” 카테고리를 삭제할까?`))return;data.categories[k]=data.categories[k].filter(c=>c.name!==n)}
ui.modal=null;saveData('삭제했어.')}
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-view],[data-action]');if(!btn)return;if(btn.dataset.view){setView(btn.dataset.view);return}let act=btn.dataset.action,id=btn.dataset.id;switch(act){case 'backdrop':if(e.target===btn)closeModal();break;case 'close':closeModal();break;case 'new-tx':showModal('tx');break;case 'edit-tx':showModal('tx',id);break;case 'new-budget':showModal('budget');break;case 'edit-budget':showModal('budget',id);break;case 'new-goal':showModal('goal');break;case 'edit-goal':showModal('goal',id);break;case 'contribute':showModal('contribute',id);break;case 'new-account':showModal('account');break;case 'edit-account':showModal('account',id);break;case 'new-recurring':showModal('recurring');break;case 'edit-recurring':showModal('recurring',id);break;case 'new-category':ui.type=btn.dataset.type;showModal('category');break;case 'tx-type':ui.type=btn.dataset.value;render();break;case 'tx-filter':ui.filter=btn.dataset.value;render();break;case 'stats-type':ui.visibleStats=btn.dataset.value;render();break;case 'month':ui.month=monthShift(ui.month,Number(btn.dataset.step));render();break;case 'auth-mode':ui.authMode=btn.dataset.value;render();break;case 'toggle-hidden':data.preferences.hideMoney=!data.preferences.hideMoney;saveData();break;case 'blank':if(confirm('샘플 데이터를 지우고 빈 가계부로 시작할까? 이 작업은 되돌릴 수 없어.')){data=blankData();saveData('빈 가계부로 시작했어.')}break;case 'delete-tx':deleteItem('tx',id);break;case 'delete-goal':deleteItem('goal',id);break;case 'delete-budget':deleteItem('budget',id);break;case 'delete-account':deleteItem('account',id);break;case 'delete-recurring':deleteItem('recurring',id);break;case 'delete-category':deleteItem('category',id,{kind:btn.dataset.type,name:btn.dataset.name});break;case 'export-json':backupJSON();break;case 'export-csv':exportCSV();break;case 'sync-now':await syncCloud();break;case 'logout':await logout();break;case 'upload-local':await uploadLocal();break;}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(['tx','goal','budget','account','recurring','contribute','category'].includes(form.dataset.form)){submitForm(form);return}if(form.dataset.form==='auth'){await signInOrUp(form);return}if(form.dataset.form==='cloud-config'){let fd=new FormData(form),url=String(fd.get('url')||'').trim().replace(/\/$/,''),key=String(fd.get('key')||'').trim();if(!/^https:\/\/[a-z0-9.-]+\.supabase\.co$/.test(url))return toast('Supabase의 https://...supabase.co 프로젝트 URL을 입력해 줘.');if(!key||key.length<15||key.toLowerCase().includes('secret')||key.toLowerCase().includes('service_role'))return toast('공개 publishable/anon 키만 입력해 줘.');config={url,key};localStorage.setItem(CLOUD_KEY,JSON.stringify(config));toast('프로젝트 연결 정보를 저장했어.');render()}});
document.addEventListener('change',e=>{if(e.target.matches('[data-recurring]')){let r=byId(data.recurring,e.target.dataset.recurring);if(r){r.active=e.target.checked;saveData('정기 결제 설정을 변경했어.')}}if(e.target.id==='backup-file'){restoreJSON(e.target.files?.[0])}if(e.target.id==='tx-search'){ui.search=e.target.value.trim();render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal){closeModal();return}if(e.key==='Enter'&&e.target.id==='tx-search'){e.preventDefault();ui.search=e.target.value.trim();render()}});
window.addEventListener('online',()=>{if(session&&ui.sync!=='synced')syncCloud()});
render();
if(session){loadCloud()}
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
